//! Exact SELECT name reflection and native submission names.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><form id=form><select id=select name=initial><option value=one>One</option><option value=two>Two</option></select><input id=neighbor value=seed></form></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://select-name.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn select_name_canonical_descriptor_and_real_attribute(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('select'),a=Object.getOwnPropertyDescriptor(HTMLSelectElement.prototype,'name');if(!a||!a.enumerable||!a.configurable||a.get.length!==0||a.set.length!==1||a.get.name!=='get name'||a.set.name!=='set name'||Object.hasOwn(x,'name')||x.name!=='initial')throw 'canonical SELECT name';");}
#[test]
fn select_name_native_exact_record_observation_and_live_named_lookup(){let(mut d,mut f,mut p)=fixture();let select=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("select")).unwrap();run(&mut d,&mut f,&mut p,r"var x=document.getElementById('select'),attr=x.getAttributeNode('name'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});var raw=document.getElementsByName('A\ud800Z'),literal=document.getElementsByName('A\ufffdZ');x.name='A\ud800Z';var records=watch.takeRecords();if(x.name!=='A\ud800Z'||x.getAttribute('name')!=='A\ud800Z'||x.getAttributeNode('name')!==attr||attr.value!==x.name||raw.length!==1||raw[0]!==x||literal.length!==0||records.length!==1||records[0].attributeName!=='name'||records[0].oldValue!=='initial'||x.value!=='one'||x.selectedIndex!==0)throw 'exact name authority';");assert_eq!(f.controls[&select].name,"A\u{fffd}Z");}
#[test]
fn select_name_inert_namespace_and_actual_cloned_attribute(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r"var owner=new Document(),x=owner.createElementNS('http://www.w3.org/1999/xhtml','p:select');x.setAttributeNS('urn:foreign','name','foreign');x.setAttributeNS(null,'NAME','upper');if(x.name!=='')throw 'exact name namespace';x.name='A\udfffZ';var attr=x.getAttributeNodeNS(null,'name'),copy=x.cloneNode(false);if(x.name!=='A\udfffZ'||copy.name!==x.name||copy.getAttributeNodeNS(null,'name')===attr||copy.ownerDocument!==owner)throw 'inert exact name copy';copy.name='Other';if(x.name!=='A\udfffZ'||copy.name!=='Other')throw 'independent names';");}

#[test]
fn select_name_conversion_reentry_abrupt_symbol_and_current_attr_identity(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('select'),old=x.getAttributeNode('name'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});var calls=0;x.name={toString:function(){calls++;x.removeAttribute('name');x.setAttribute('name','replacement');return 'A\ud800Z';}};var current=x.getAttributeNode('name'),records=watch.takeRecords();if(calls!==1||current===old||old.ownerElement!==null||old.value!=='initial'||current.value!=='A\ud800Z'||records.length!==3||records[2].oldValue!=='replacement')throw 'current real Attr after conversion';var marker={},caught;try{x.name={toString:function(){x.setAttribute('name','author effect');throw marker;}};}catch(e){caught=e;}records=watch.takeRecords();if(caught!==marker||x.name!=='author effect'||records.length!==1||records[0].oldValue!=='A\ud800Z')throw 'abrupt conversion preserves author effect';caught=false;try{x.name=Symbol('optgroup');}catch(e){caught=e instanceof TypeError;}if(!caught||watch.takeRecords().length||x.name!=='author effect')throw 'Symbol conversion refusal';for(var value of [null,undefined,0,false]){x.name=value;if(x.name!==String(value))throw 'ordinary DOMString conversion';}if(x.firstChild.textContent!=='One')throw 'metadata leaves displayed text';"#);
}




#[test]
fn select_name_descriptors_brands_author_override_and_saved_constructor(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('select'),C=HTMLSelectElement,P=C.prototype,a=Object.getOwnPropertyDescriptor(P,'name'),calls=0;for(var bad of [{},Object.create(P),document.body,document.createElementNS('urn:foreign','select'),new Document().createElementNS('http://www.w3.org/1999/xhtml','SELECT')]){var caught=false;try{a.get.call(bad);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'getter concrete brand';caught=false;try{a.set.call(bad,{toString:function(){calls++;return 'bad';}});}catch(e){caught=e instanceof TypeError;}if(!caught||calls)throw 'brand before conversion';}Object.defineProperty(x,'name',{value:'author',writable:true,configurable:true});if(x.name!=='author'||a.get.call(x)!=='initial')throw 'canonical authority';a.set.call(x,'canonical');if(x.name!=='author'||x.getAttribute('name')!=='canonical')throw 'borrowed real setter';delete x.name;if(x.name!=='canonical'||Object.hasOwn(x,'name'))throw 'restored inherited reflection';delete window.HTMLSelectElement;if(!(x instanceof C)||Object.getPrototypeOf(x)!==P)throw 'saved original interface';"#);
}


#[test]
fn select_name_saved_child_origin_precedes_conversion_and_recovers(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('select'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var C=frame.contentWindow.HTMLSelectElement,a=Object.getOwnPropertyDescriptor(C.prototype,'name'),calls=0;if(C===HTMLSelectElement||a.get.call(x)!=='initial')throw 'captured area accessor';"#);p.set_location(&crate::navigation::address("https://other-time.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;for source in ["a.get.call(x);","a.set.call(x,{toString:function(){calls++;return 'bad';}});"]{p.begin_job();let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);}p.set_location(&crate::navigation::address("https://select-name.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls)throw 'origin precedes conversion';a.set.call(x,'recovered');if(a.get.call(x)!=='recovered')throw 'area origin recovery';");
}

// Shared reflection transactions must refuse before observable changes.


#[test]
fn select_name_writer_refusal_preserves_native_and_inert_records_and_recovers(){
 for inert in [false,true]{for source in [r"x.name='Long canonical \ud800 DateTime replacement';",r"x.setAttribute('name','Long canonical \ud800 DateTime replacement');",r"attr.value='Long canonical \ud800 DateTime replacement';",r"attr.nodeValue='Long canonical \ud800 DateTime replacement';",r"attr.textContent='Long canonical \ud800 DateTime replacement';"]{for mode in 0..5{
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','select');x.setAttribute('name','one');"}else{"var x=document.getElementById('select');x.setAttribute('name','one');"});run(&mut d,&mut f,&mut p,"var attr=x.getAttributeNode('name'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone());let controls=f.controls.iter().map(|(n,c)|(*n,c.owner,c.name.clone(),c.value.text(),c.disabled,c.checked,format!("{:?}",c.select),c.caption.clone())).collect::<Vec<_>>();let limit=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,3=>p.state.limits.host.string_bytes=1,_=>p.state.execution_deadline=Some(Instant::now())};let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).expect_err(&format!("alt writer {inert}/{source}/{mode}"));assert!(e.contains("work")||e.contains("allowance")||e.contains("limit")||e.contains("bound"),"{inert}/{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone()),state);assert_eq!(f.controls.iter().map(|(n,c)|(*n,c.owner,c.name.clone(),c.value.text(),c.disabled,c.checked,format!("{:?}",c.select),c.caption.clone())).collect::<Vec<_>>(),controls);p.state.retained_limit=limit;p.state.limits.host.string_bytes=strings;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(attr.value!=='one'||x.name!=='one'||watch.takeRecords().length)throw 'atomic alt writer refusal';");run(&mut d,&mut f,&mut p,source);run(&mut d,&mut f,&mut p,r"var records=watch.takeRecords();if(x.name!=='Long canonical \ud800 DateTime replacement'||records.length!==1||records[0].oldValue!=='one'||records[0].attributeName!=='name'||x.getAttributeNode('name')!==attr)throw 'fresh alt writer recovery';");
 }}}
}


#[test]
fn select_name_reads_enforce_work_copy_string_and_deadline_without_retained_growth(){
 for inert in [false,true]{for mode in 0..5{let(mut d,mut f,mut p)=fixture();let object=if inert{run(&mut d,&mut f,&mut p,r"var time=new Document().createElementNS('http://www.w3.org/1999/xhtml','select');time.name='A\ud800Z';");let Value::Host(object)=p.runtime.execute("time;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("inert select handle")};object}else{run(&mut d,&mut f,&mut p,r"document.getElementById('select').name='A\ud800Z';");node_handle((0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("select")).unwrap())};let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());let limit=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.limits.host.string_bytes=1,3=>p.state.execution_deadline=Some(Instant::now()),_=>p.state.retained_limit=p.state.retained};let result=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.select_name_get(object);if mode==4{assert!(result.is_ok());}else{let e=result.unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("time")||e.contains("bound"),"{e}");}assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);p.state.execution_deadline=None;p.state.retained_limit=limit;p.state.limits.host.string_bytes=strings;p.begin_job();assert!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.select_name_get(object).is_ok());}}
}




#[test]
fn select_name_native_and_inert_exact_attached_aliases_and_namespace(){
 for inert in [false,true]{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','select');x.setAttribute('name','one');"}else{"var x=document.getElementById('select');x.setAttribute('name','one');"});run(&mut d,&mut f,&mut p,if inert{"var expectedRemoved='';"}else{"var expectedRemoved='';"});run(&mut d,&mut f,&mut p,r#"var a=x.getAttributeNode('name');for(var writer of ['value','nodeValue','textContent']){a[writer]='R\ud800'+writer;if(x.name!=='R\ud800'+writer||x.getAttributeNode('name')!==a)throw 'exact attached alias';}x.setAttributeNS('urn:foreign','name','foreign');x.setAttributeNS(null,'NAME','upper');if(x.name!=='R\ud800textContent'||x.getAttributeNodeNS(null,'name')!==a)throw 'exact null namespace/local name';x.setAttributeNS(null,'name','alternative');if(x.name!=='alternative'||a.value!==x.name)throw 'null namespace writer';x.removeAttributeNS(null,'name');if(x.name!==expectedRemoved||a.ownerElement!==null||a.value!=='alternative')throw 'removed actual alt';"#);}
}



#[test]
fn select_name_native_serialization_raw_alias_remove_and_reset(){
 let(mut d,mut f,mut p)=fixture();let owner=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("form")).unwrap();let select=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("select")).unwrap();let location=crate::navigation::address("https://select-name.test/source",&crate::navigation::Location::home()).unwrap();
 for (source,query) in [(r"var x=document.getElementById('select');x.name='A\ud800 Z';","A%EF%BF%BD+Z=one"),("var attr=x.getAttributeNode('name');attr.nodeValue='changed';x.selectedIndex=1;","changed=two"),("x.removeAttributeNode(attr);",""),("x.setAttributeNS(null,'name','restored');","restored=two")]{p.begin_job();run(&mut d,&mut f,&mut p,source);assert_eq!(f.script_submit_request(&d,owner,&location,&location).unwrap().location.url.unwrap().query.as_deref().unwrap_or(""),query);}
 f.reset_in_document(&d,owner).unwrap();assert_eq!(f.controls[&select].name,"restored");assert_eq!(f.script_submit_request(&d,owner,&location,&location).unwrap().location.url.unwrap().query.as_deref(),Some("restored=one"));run(&mut d,&mut f,&mut p,"if(x.name!=='restored'||x.value!=='one'||attr.ownerElement!==null||attr.value!=='changed')throw 'native reset retains current name';");
}
#[test]
fn select_name_native_editor_defaults_flags_and_events_preserved(){let(mut d,mut f,mut p)=fixture();let select=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("select")).unwrap();run(&mut d,&mut f,&mut p,"var x=document.getElementById('select'),events=0;x.oninput=function(){events++;};x.onchange=function(){events++;};x.selectedIndex=1;");{let c=f.controls.get_mut(&select).unwrap();c.value.cursor=2;c.value.anchor=1;c.value.offset=1;}let c=&f.controls[&select];let before=(c.value.text(),c.value.cursor,c.value.anchor,c.value.offset,c.caption.clone(),format!("{:?}",c.select),c.disabled,c.required,c.dirty_value);run(&mut d,&mut f,&mut p,"x.name='new name';if(x.name!=='new name'||x.value!=='two'||x.selectedIndex!==1||events)throw 'name preserves selection';");let c=&f.controls[&select];assert_eq!((c.value.text(),c.value.cursor,c.value.anchor,c.value.offset,c.caption.clone(),format!("{:?}",c.select),c.disabled,c.required,c.dirty_value),before);assert!(!p.has_navigation_request());assert!(p.take_dynamic_scripts().is_empty()&&p.take_dynamic_stylesheets().is_empty());assert!(!p.state.images.has_changes());}
#[test]
fn select_name_native_byte_limit_stable_storage_and_atomic_refusal(){let(mut d,mut f,mut p)=fixture();let select=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("select")).unwrap();run(&mut d,&mut f,&mut p,"var x=document.getElementById('select'),edge='';for(var n=0;n<8192;n++)edge+='a';var over=edge+'b';x.name=edge;var attr=x.getAttributeNode('name'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});");assert_eq!(f.controls[&select].name.len(),8192);let retained=p.state.retained;for _ in 0..3{p.begin_job();run(&mut d,&mut f,&mut p,"x.name=edge;watch.takeRecords();");assert_eq!(p.state.retained,retained);}let tree=format!("{:?}",d.nodes);let commits=p.state.dom_commits;for source in ["x.name=over;","x.setAttribute('name',over);","attr.value=over;"]{p.begin_job();let error=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("8192"),"{error}");assert_eq!(format!("{:?}",d.nodes),tree);assert_eq!(f.controls[&select].name.len(),8192);assert_eq!(p.state.dom_commits,commits);}p.begin_job();run(&mut d,&mut f,&mut p,"if(watch.takeRecords().length||x.name!==edge)throw 'atomic native name limit';x.name='recovered';");assert_eq!(f.controls[&select].name,"recovered");}
#[test]
fn select_name_native_aggregate_payload_refusal_and_fresh_recovery(){let mut source=String::from("<form id=form><select id=select name=initial><option value=one>One</option><option value=two>Two</option></select>");for n in 0..16{source.push_str(&format!("<input id=neighbor{n} value=seed>"));}source.push_str("</form>");let mut d=crate::html::parse(&source);d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);let select=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("select")).unwrap();run(&mut d,&mut f,&mut p,"var x=document.getElementById('select'),attr=x.getAttributeNode('name'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});");let base=f.controls.values().map(|c|c.name.len()+c.value.text().len()+c.select.as_ref().map_or(0,|s|s.options.iter().map(|o|o.value.len()+o.label.len()).sum::<usize>())).sum::<usize>();let mut remaining=128*1024-base-5;for c in f.controls.values_mut().filter(|c|c.kind==forms::Kind::Text){let n=remaining.min(8192);c.name="n".repeat(n);remaining-=n;}assert_eq!(remaining,0);let tree=format!("{:?}",d.nodes);let before=(p.state.retained,p.state.dom_commits);for source in ["x.name='Longer control name';","attr.value='Longer control name';"]{p.begin_job();let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("128 KiB"),"{e}");assert_eq!(format!("{:?}",d.nodes),tree);assert_eq!(f.controls[&select].name,"initial");assert_eq!((p.state.retained,p.state.dom_commits),before);}for c in f.controls.values_mut().filter(|c|c.kind==forms::Kind::Text){c.name.clear();}p.begin_job();run(&mut d,&mut f,&mut p,"if(watch.takeRecords().length||attr.value!=='initial')throw 'aggregate atomic refusal';x.name='recovered';");assert_eq!(f.controls[&select].name,"recovered");}
